update vm_overdue_remind_t
set industry_code = #{targetIndustryCode}
where SUBSTRING(warning_order_id, 9) like concat(#{tenantId}, '%') and industry_code = #{sourceIndustryCode}

update vm_alarm_flow_config
set industry_code = #{targetIndustryCode}, app_ver_code = #{targetAppVerCode}
where tenant_id = #{tenantId} and industry_code = #{sourceIndustryCode} and app_ver_code = #{sourceAppVerCode}
